#include <stdlib.h>
#include <string.h>
#include <omp.h>
#include <immintrin.h>

#if defined(__AVX512F__)
#define VW 16
#define MR 12
#define ROWS(X) X(0) X(1) X(2) X(3) X(4) X(5) X(6) X(7) X(8) X(9) X(10) X(11)
#else
#define VW 8
#define MR 6
#define ROWS(X) X(0) X(1) X(2) X(3) X(4) X(5)
#endif
#define NR (2 * VW)
#define KCMAX 256
#define NCW 256
#define NCP (NCW / NR)

typedef float vf __attribute__((vector_size(VW * 4)));

static inline vf ldu(const float *p) { vf v; memcpy(&v, p, sizeof(v)); return v; }
static inline void stu(float *p, vf v) { memcpy(p, &v, sizeof(v)); }

static float *g_Ap = NULL, *g_Bp = NULL;
static size_t g_acap = 0, g_bcap = 0;

static float *grow(float *p, size_t *cap, size_t need)
{
    if (need <= *cap) return p;
    free(p);
    need = (need + 4095) & ~(size_t)4095;
    p = (float *)aligned_alloc(4096, need);
    *cap = need;
    return p;
}

static void kernel(int kc, const float *restrict a, const float *restrict b,
                   float *restrict c, int ldc, int mr, int nr, int accum)
{
#define PFC(i) if ((i) < mr) { __builtin_prefetch(c + (size_t)(i) * ldc, 1, 3); \
                               __builtin_prefetch(c + (size_t)(i) * ldc + NR - 1, 1, 3); }
    ROWS(PFC)
#undef PFC

#define DECL(i) vf c##i##_0 = {0}, c##i##_1 = {0};
    ROWS(DECL)
#undef DECL

#pragma GCC unroll 4
    for (int k = 0; k < kc; k++) {
        vf b0 = *(const vf *)(b);
        vf b1 = *(const vf *)(b + VW);
#define FMA(i) { vf av = (vf){0} + a[i]; c##i##_0 += av * b0; c##i##_1 += av * b1; }
        ROWS(FMA)
#undef FMA
        a += MR;
        b += NR;
    }

    if (mr == MR && nr == NR) {
        if (accum) {
#define STA(i) { float *r = c + (size_t)(i) * ldc; \
                 stu(r, ldu(r) + c##i##_0); stu(r + VW, ldu(r + VW) + c##i##_1); }
            ROWS(STA)
#undef STA
        } else {
#define STS(i) { float *r = c + (size_t)(i) * ldc; stu(r, c##i##_0); stu(r + VW, c##i##_1); }
            ROWS(STS)
#undef STS
        }
    } else {
#if defined(__AVX512F__)
        __mmask16 m0 = nr >= 16 ? (__mmask16)0xFFFF : (__mmask16)((1u << nr) - 1);
        __mmask16 m1 = nr >= 32 ? (__mmask16)0xFFFF
                     : nr <= 16 ? (__mmask16)0 : (__mmask16)((1u << (nr - 16)) - 1);
#define STM(i) if ((i) < mr) { float *r = c + (size_t)(i) * ldc; \
            __m512 t0 = (__m512)c##i##_0, t1 = (__m512)c##i##_1; \
            if (accum) { t0 = _mm512_add_ps(t0, _mm512_maskz_loadu_ps(m0, r)); \
                         t1 = _mm512_add_ps(t1, _mm512_maskz_loadu_ps(m1, r + 16)); } \
            _mm512_mask_storeu_ps(r, m0, t0); _mm512_mask_storeu_ps(r + 16, m1, t1); }
        ROWS(STM)
#undef STM
#else
        float tmp[MR * NR] __attribute__((aligned(64)));
#define STT(i) { *(vf *)(tmp + (i) * NR) = c##i##_0; *(vf *)(tmp + (i) * NR + VW) = c##i##_1; }
        ROWS(STT)
#undef STT
        if (accum) {
            for (int i = 0; i < mr; i++)
                for (int j = 0; j < nr; j++)
                    c[(size_t)i * ldc + j] += tmp[i * NR + j];
        } else {
            for (int i = 0; i < mr; i++)
                for (int j = 0; j < nr; j++)
                    c[(size_t)i * ldc + j] = tmp[i * NR + j];
        }
#endif
    }
}

#if defined(__AVX512F__)
/* in-place 16x16 transpose: on return r[k] holds column k (rows 0..15) */
static inline __attribute__((always_inline)) void transpose16(__m512 *r)
{
    __m512 u[16];
#pragma GCC unroll 4
    for (int g = 0; g < 4; g++) {
        __m512d lo_ab = _mm512_castps_pd(_mm512_unpacklo_ps(r[4 * g], r[4 * g + 1]));
        __m512d hi_ab = _mm512_castps_pd(_mm512_unpackhi_ps(r[4 * g], r[4 * g + 1]));
        __m512d lo_cd = _mm512_castps_pd(_mm512_unpacklo_ps(r[4 * g + 2], r[4 * g + 3]));
        __m512d hi_cd = _mm512_castps_pd(_mm512_unpackhi_ps(r[4 * g + 2], r[4 * g + 3]));
        u[4 * g + 0] = _mm512_castpd_ps(_mm512_unpacklo_pd(lo_ab, lo_cd));
        u[4 * g + 1] = _mm512_castpd_ps(_mm512_unpackhi_pd(lo_ab, lo_cd));
        u[4 * g + 2] = _mm512_castpd_ps(_mm512_unpacklo_pd(hi_ab, hi_cd));
        u[4 * g + 3] = _mm512_castpd_ps(_mm512_unpackhi_pd(hi_ab, hi_cd));
    }
#pragma GCC unroll 4
    for (int c = 0; c < 4; c++) {
        __m512 x01e = _mm512_shuffle_f32x4(u[c], u[4 + c], 0x88);
        __m512 x01o = _mm512_shuffle_f32x4(u[c], u[4 + c], 0xdd);
        __m512 x23e = _mm512_shuffle_f32x4(u[8 + c], u[12 + c], 0x88);
        __m512 x23o = _mm512_shuffle_f32x4(u[8 + c], u[12 + c], 0xdd);
        r[c]      = _mm512_shuffle_f32x4(x01e, x23e, 0x88);
        r[8 + c]  = _mm512_shuffle_f32x4(x01e, x23e, 0xdd);
        r[4 + c]  = _mm512_shuffle_f32x4(x01o, x23o, 0x88);
        r[12 + c] = _mm512_shuffle_f32x4(x01o, x23o, 0xdd);
    }
}
#endif

/* panel r: rows r*MR..r*MR+MR-1 of A, layout [k][MR] over all k */
static void pack_a_panel(const float *A, float *restrict dst, int r, int n)
{
    int row0 = r * MR;
    int mr = n - row0 < MR ? n - row0 : MR;
    const float *src = A + (size_t)row0 * n;
    int k0 = 0;
    if (mr == MR) {
        const float *s[MR];
        for (int i = 0; i < MR; i++) s[i] = src + (size_t)i * n;
#if defined(__AVX512F__)
        for (; k0 + 16 <= n; k0 += 16) {
            __m512 rw[16];
#pragma GCC unroll 16
            for (int i = 0; i < 16; i++)
                rw[i] = i < MR ? _mm512_loadu_ps(s[i < MR ? i : 0] + k0) : _mm512_setzero_ps();
            transpose16(rw);
            float *d = dst + (size_t)k0 * MR;
#pragma GCC unroll 16
            for (int k = 0; k < 16; k++)
                _mm512_mask_storeu_ps(d + k * MR, (__mmask16)0x0FFF, rw[k]);
        }
#endif
        for (; k0 < n; k0++) {
            float *d = dst + (size_t)k0 * MR;
#pragma GCC unroll 16
            for (int i = 0; i < MR; i++) d[i] = s[i][k0];
        }
    } else {
        for (; k0 < n; k0++) {
            float *d = dst + (size_t)k0 * MR;
            int i = 0;
            for (; i < mr; i++) d[i] = src[(size_t)i * n + k0];
            for (; i < MR; i++) d[i] = 0.0f;
        }
    }
}

/* panel p: cols p*NR..p*NR+NR-1 of B, layout [k][NR] over all k */
static void pack_b_panel(const float *B, float *restrict dst, int p, int n)
{
    int j0 = p * NR;
    int nr = n - j0 < NR ? n - j0 : NR;
    const float *src = B + j0;
    if (nr == NR) {
        for (int k = 0; k < n; k++)
            memcpy(dst + (size_t)k * NR, src + (size_t)k * n, NR * sizeof(float));
    } else {
        for (int k = 0; k < n; k++) {
            int j = 0;
            for (; j < nr; j++) dst[(size_t)k * NR + j] = src[(size_t)k * n + j];
            for (; j < NR; j++) dst[(size_t)k * NR + j] = 0.0f;
        }
    }
}

void matmul(const float *A, const float *B, float *C, int n)
{
    if (n <= 0) return;
    int mp = (n + MR - 1) / MR;
    int np = (n + NR - 1) / NR;

    g_Ap = grow(g_Ap, &g_acap, (size_t)mp * MR * n * sizeof(float));
    g_Bp = grow(g_Bp, &g_bcap, (size_t)np * NR * n * sizeof(float));
    float *Ap = g_Ap, *Bp = g_Bp;

    int nkb = (n + KCMAX - 1) / KCMAX;
    int kcb = (n + nkb - 1) / nkb;

    int nth = omp_get_max_threads();
    int ntn = (np + NCP - 1) / NCP;
    int mpt = (mp * ntn) / (4 * nth);
    if (mpt < 1) mpt = 1;
    if (mpt > 8) mpt = 8;
    int ntm = (mp + mpt - 1) / mpt;

    #pragma omp parallel proc_bind(close)
    {
        #pragma omp for schedule(dynamic, 2)
        for (int t = 0; t < mp + np; t++) {
            if (t < mp) pack_a_panel(A, Ap + (size_t)t * n * MR, t, n);
            else        pack_b_panel(B, Bp + (size_t)(t - mp) * n * NR, t - mp, n);
        }

        #pragma omp for schedule(dynamic, 1) collapse(2)
        for (int ti = 0; ti < ntm; ti++) {
            for (int tj = 0; tj < ntn; tj++) {
                int p0 = ti * mpt, p1 = p0 + mpt < mp ? p0 + mpt : mp;
                int q0 = tj * NCP, q1 = q0 + NCP < np ? q0 + NCP : np;
                for (int pc = 0; pc < n; pc += kcb) {
                    int kc = n - pc < kcb ? n - pc : kcb;
                    int accum = pc > 0;
                    for (int p = p0; p < p1; p++) {
                        int i0 = p * MR;
                        int mr = n - i0 < MR ? n - i0 : MR;
                        const float *ap = Ap + (size_t)p * n * MR + (size_t)pc * MR;
                        float *crow = C + (size_t)i0 * n;
                        for (int q = q0; q < q1; q++) {
                            int j0 = q * NR;
                            int nr = n - j0 < NR ? n - j0 : NR;
                            const float *bp = Bp + (size_t)q * n * NR + (size_t)pc * NR;
                            kernel(kc, ap, bp, crow + j0, n, mr, nr, accum);
                        }
                    }
                }
            }
        }
    }
}
